(()=>{
const root=document.documentElement,entrance=document.querySelector('.site-entrance');if(!entrance)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),hero=document.querySelector('.hero'),sun=entrance.querySelector('.entrance-sun'),landscape=entrance.querySelector('.entrance-landscape'),logo=document.querySelector('.brand img'),chapter=entrance.querySelector('.entrance-chapter');let animations=[],timers=[],running=false,returnFocus;
const animate=(el,frames,options)=>{const a=el.animate(frames,{fill:'forwards',...options});animations.push(a);return a;};
function clear(){clearTimeout(window.__entranceSafety);timers.forEach(clearTimeout);timers=[];animations.forEach(a=>a.cancel());animations=[];}
function finish({startHero=true}={}){if(!running&&!root.classList.contains('entrance-pending'))return;running=false;clear();entrance.classList.remove('is-active','is-docking');entrance.setAttribute('aria-hidden','true');root.classList.remove('entrance-pending','entrance-reveal');hero?.classList.remove('entrance-arriving');logo.style.opacity='';document.querySelector('.brand').style.opacity='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else document.querySelector('.brand').focus({preventScroll:true});hero?.classList.add('after-entrance');if(startHero)document.dispatchEvent(new Event('entrance-complete'));}
function dock(){if(!running)return;root.classList.remove('entrance-pending');root.classList.add('entrance-reveal');entrance.classList.add('is-docking');hero.classList.add('entrance-arriving');const target=logo.getBoundingClientRect(),current=sun.getBoundingClientRect(),heroRect=hero.getBoundingClientRect();sun.getAnimations().forEach(a=>a.cancel());sun.style.cssText=`left:${current.left}px;top:${current.top}px;width:${current.width}px;height:${current.height}px;transform:none;opacity:1;`;
animate(sun,[{left:current.left+'px',top:current.top+'px',width:current.width+'px',height:current.height+'px',opacity:1},{left:target.left+'px',top:target.top+'px',width:target.width+'px',height:target.height+'px',opacity:1}],{duration:1350,easing:'cubic-bezier(.65,0,.2,1)'});
animate(entrance.querySelector('.sun-corona'),[{opacity:1,transform:'translate(-50%,-50%) scale(1)'},{opacity:0,transform:'translate(-50%,-50%) scale(.35)'}],{duration:600});
const heroImage=hero.querySelector('.hero-photo');const finalPosition=getComputedStyle(heroImage).objectPosition;landscape.querySelectorAll('img').forEach(img=>animate(img,[{objectPosition:getComputedStyle(img).objectPosition},{objectPosition:finalPosition}],{duration:1350,easing:'ease-in-out'}));animate(landscape,[{top:'0px',height:innerHeight+'px',bottom:'auto',opacity:1,offset:0},{top:Math.max(0,heroRect.top)+'px',height:heroRect.height+'px',bottom:'auto',opacity:1,offset:.7},{top:Math.max(0,heroRect.top)+'px',height:heroRect.height+'px',bottom:'auto',opacity:0,offset:1}],{duration:1350,easing:'cubic-bezier(.55,0,.2,1)'});for(const selector of ['body>header','body>.topbar']){const el=document.querySelector(selector);if(el)animate(el,[{opacity:0},{opacity:1}],{duration:1100});}
for(const sel of ['.entrance-title','.entrance-footer','.entrance-letterbox.top','.entrance-letterbox.bottom','.entrance-progress'])animate(entrance.querySelector(sel),[{opacity:1},{opacity:0}],{duration:450});
timers.push(setTimeout(()=>{hero.classList.remove('entrance-arriving');hero.querySelector('.hero-content').animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:700,easing:'ease-out'});},650));timers.push(setTimeout(()=>finish(),1400));}
function play(){try{sessionStorage.setItem('nearshore-entrance-seen','1');}catch{document.cookie='nearshore_intro_seen=1; Path=/; SameSite=Lax';}if(reduced.matches){root.classList.remove('entrance-pending');return;}if(running)finish({startHero:false});returnFocus=document.activeElement?.closest('#replay-entrance');clear();running=true;sun.style.cssText='';root.classList.add('entrance-pending');root.classList.remove('entrance-reveal');entrance.classList.add('is-active');entrance.classList.remove('is-docking');entrance.setAttribute('aria-hidden','false');window.scrollTo({top:0,behavior:'instant'});document.dispatchEvent(new Event('entrance-start'));entrance.querySelector('.entrance-skip').focus({preventScroll:true});chapter.textContent='01 / BEFORE THE SHORE AWAKES';
const duration=5700;
animate(entrance.querySelector('.entrance-dawn'),[{opacity:1,offset:0},{opacity:.95,offset:.28},{opacity:.6,offset:.62},{opacity:0,offset:1}],{duration,easing:'ease-in-out'});
animate(entrance.querySelector('.entrance-night'),[{opacity:1},{opacity:.8,offset:.3},{opacity:0}],{duration,easing:'ease-in'});
animate(entrance.querySelector('.entrance-horizon'),[{opacity:0},{opacity:.85,offset:.52},{opacity:.5,offset:.8},{opacity:.05}],{duration,easing:'ease-in-out'});
animate(entrance.querySelector('.entrance-clouds'),[{transform:'translateX(-3%)',opacity:.15},{transform:'translateX(4%)',opacity:.35,offset:.6},{transform:'translateX(6%)',opacity:0}],{duration,easing:'linear'});
animate(landscape,[{transform:'scale(1.065)'},{transform:'scale(1)'}],{duration,easing:'cubic-bezier(.2,.5,.4,1)'});
animate(sun,[{left:'55%',top:'66%',opacity:0,offset:0},{left:'55%',top:'57%',opacity:1,offset:.17},{left:'55%',top:'34%',opacity:1,offset:.7},{left:'55%',top:'29%',opacity:1,offset:1}],{duration,easing:'cubic-bezier(.2,.4,.3,1)'});
animate(entrance.querySelector('.sun-corona'),[{opacity:.4},{opacity:1,offset:.6},{opacity:.85}],{duration});
animate(entrance.querySelector('.entrance-foreground'),[{opacity:1,filter:'brightness(.25) saturate(.6)'},{opacity:.8,filter:'brightness(.55) saturate(.8)',offset:.45},{opacity:0,filter:'brightness(1) saturate(1)',offset:.86},{opacity:0}],{duration,easing:'ease-in-out'});
animate(entrance.querySelector('.entrance-title'),[{opacity:0,transform:'translateY(28px)',clipPath:'inset(100% 0 0 0)',offset:0},{opacity:0,transform:'translateY(28px)',clipPath:'inset(100% 0 0 0)',offset:.35},{opacity:1,transform:'translateY(0)',clipPath:'inset(0)',offset:.6},{opacity:1,transform:'translateY(0)',clipPath:'inset(0)',offset:1}],{duration,easing:'ease-out'});
animate(entrance.querySelector('.entrance-progress>span'),[{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration:7100,easing:'linear'});
timers.push(setTimeout(()=>chapter.textContent='02 / A NEW DAY TAKES SHAPE',1700),setTimeout(()=>chapter.textContent='03 / PROTECTION FROM THE FIRST LIGHT',3700),setTimeout(dock,duration),setTimeout(()=>finish(),9500));}
entrance.querySelector('.entrance-skip').addEventListener('click',()=>finish());document.querySelector('#replay-entrance')?.addEventListener('click',play);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&running)finish();});reduced.addEventListener('change',()=>{if(reduced.matches)finish();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)finish();});addEventListener('resize',()=>{if(entrance.classList.contains('is-docking'))finish();},{passive:true});
if(root.classList.contains('entrance-pending')){const plate=entrance.querySelector('.entrance-dawn');Promise.race([Promise.all([plate.decode().catch(()=>{}),logo.decode().catch(()=>{})]),new Promise(resolve=>setTimeout(resolve,600))]).then(()=>{if(root.classList.contains('entrance-pending'))play();});}
})();
